import { MakeLogicType, actions, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { signalsReportSpend } from 'products/signals/frontend/generated/api'
import type { ReportSpendApi } from 'products/signals/frontend/generated/api.schemas'

export interface ReportSpendLogicProps {
    teamId: number
    reportId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportSpendLogicValues {
    failed: boolean
    spend: ReportSpendApi | null
    spendLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportSpendLogicActions {
    loadSpend: () => any
    loadSpendFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSpendSuccess: (
        spend: ReportSpendApi,
        payload?: any
    ) => {
        spend: ReportSpendApi
        payload?: any
    }
    refreshSpend: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reportSpendLogicMeta {
    key: string
}

export type reportSpendLogicType = MakeLogicType<
    reportSpendLogicValues,
    reportSpendLogicActions,
    ReportSpendLogicProps,
    reportSpendLogicMeta
>

export const reportSpendLogic = kea<reportSpendLogicType>([
    props({} as ReportSpendLogicProps),
    key((props) => `${props.teamId}:${props.reportId}`),
    path((key) => ['products', 'signals', 'reportSpendLogic', key]),
    actions({ refreshSpend: true }),
    loaders(({ props }) => ({
        spend: [
            null as ReportSpendApi | null,
            { loadSpend: async () => signalsReportSpend(String(props.teamId), props.reportId) },
        ],
    })),
    reducers({
        failed: [false, { loadSpend: () => false, loadSpendSuccess: () => false, loadSpendFailure: () => true }],
    }),
    listeners(({ actions, cache, values }) => {
        const refreshIfPending = (): void => {
            if (cache.refreshPending) {
                actions.refreshSpend()
            }
        }
        return {
            refreshSpend: () => {
                cache.refreshPending = values.spendLoading
                if (!values.spendLoading) {
                    actions.loadSpend()
                }
            },
            loadSpendSuccess: refreshIfPending,
            loadSpendFailure: refreshIfPending,
        }
    }),
    afterMount(({ actions }) => actions.refreshSpend()),
])
